	case 5: to.add("  shipping_address_requested: "); ++stages.back(); if (flag & MTPDinvoice::Flag::f_shipping_address_requested) { to.add("YES [ BY BIT 4 IN FIELD flags ]"); } else { to.add("[ SKIPPED BY BIT 4 IN FIELD flags ]"); } break;
	case 6: to.add("  flexible: "); ++stages.back(); if (flag & MTPDinvoice::Flag::f_flexible) { to.add("YES [ BY BIT 5 IN FIELD flags ]"); } else { to.add("[ SKIPPED BY BIT 5 IN FIELD flags ]"); } break;
	case 7: to.add("  phone_to_provider: "); ++stages.back(); if (flag & MTPDinvoice::Flag::f_phone_to_provider) { to.add("YES [ BY BIT 6 IN FIELD flags ]"); } else { to.add("[ SKIPPED BY BIT 6 IN FIELD flags ]"); } break;
	case 8: to.add("  email_to_provider: "); ++stages.back(); if (flag & MTPDinvoice::Flag::f_email_to_provider) { to.add("YES [ BY BIT 7 IN FIELD flags ]"); } else { to.add("[ SKIPPED BY BIT 7 IN FIELD flags ]"); } break;
	case 9: to.add("  recurring: "); ++stages.back(); if (flag & MTPDinvoice::Flag::f_recurring) { to.add("YES [ BY BIT 9 IN FIELD flags ]"); } else { to.add("[ SKIPPED BY BIT 9 IN FIELD flags ]"); } break;
	case 10: to.add("  currency: "); ++stages.back(); types.push_back(mtpc_string+0); vtypes.push_back(0); stages.push_back(0); flags.push_back(0); break;
	case 11: to.add("  prices: "); ++stages.back(); types.push_back(0); vtypes.push_back(0); stages.push_back(0); flags.push_back(0); break;
	case 12: to.add("  max_tip_amount: "); ++stages.back(); if (flag & MTPDinvoice::Flag::f_max_tip_amount) { types.push_back(mtpc_long+0); vtypes.push_back(0); stages.push_back(0); flags.push_back(0); } else { to.add("[ SKIPPED BY BIT 8 IN FIELD flags ]"); } break;
	case 13: to.add("  suggested_tip_amounts: "); ++stages.back(); if (flag & MTPDinvoice::Flag::f_suggested_tip_amounts) { types.push_back(0); vtypes.push_back(mtpc_long+0); stages.push_back(0); flags.push_back(0); } else { to.add("[ SKIPPED BY BIT 8 IN FIELD flags ]"); } break;
	case 14: to.add("  terms_url: "); ++stages.back(); if (flag & MTPDinvoice::Flag::f_terms_url) { types.push_back(mtpc_string+0); vtypes.push_back(0); stages.push_back(0); flags.push_back(0); } else { to.add("[ SKIPPED BY BIT 10 IN FIELD flags ]"); } break;
	case 15: to.add("  subscription_period: "); ++stages.back(); if (flag & MTPDinvoice::Flag::f_subscription_period) { types.push_back(mtpc_int+0); vtypes.push_back(0); stages.push_back(0); flags.push_back(0); } else { to.add("[ SKIPPED BY BIT 11 IN FIELD flags ]"); } break;
