bool DumpToTextType(DumpToTextBuffer &to, const mtpPrime *&from, const mtpPrime *end, mtpPrime cons, uint32 level, mtpPrime vcons) {
	static auto kSerializers = CreateTextSerializers();

	Types types, vtypes;
	Stages stages;
	Flags flags;
	types.reserve(20); vtypes.reserve(20); stages.reserve(20); flags.reserve(20);
	types.push_back(mtpTypeId(cons)); vtypes.push_back(mtpTypeId(vcons)); stages.push_back(0); flags.push_back(0);

	mtpTypeId type = cons, vtype = vcons;
	int32 stage = 0;
	int64 flag = 0;

	while (!types.isEmpty()) {
		type = types.back();
		vtype = vtypes.back();
		stage = stages.back();
		flag = flags.back();
		if (!type) {
			if (from >= end) {
				to.error("insufficient data");
				return false;
			} else if (stage) {
				to.error("unknown type on stage > 0");
				return false;
			}
			types.back() = type = *from;
			++from;
		}

		int32 lev = level + types.size() - 1;
		auto it = kSerializers.find(type);
		if (it != kSerializers.end()) {
			if (!(*it->second)(to, stage, lev, types, vtypes, stages, flags, from, end, flag)) {
				to.error();
				return false;
			}
		} else if (DumpToTextCore(to, from, end, type, lev, vtype)) {
			types.pop_back(); vtypes.pop_back(); stages.pop_back(); flags.pop_back();
		} else {
			to.error();

			const auto bad = QByteArray::number(type, 16);
			to.add("(ERROR_SCHEME_BAD_CONS:0x").add(bad.data()).add(")");

			return false;
		}
	}
	return true;
}

